public class Main {
    public static double milesToKilometers(double miles) {
        if (!Double.isFinite(miles) || miles < 0) throw new IllegalArgumentException("Miles must be finite and non-negative");
        return miles * 1.609344;
    }
    public static double kilometersToMiles(double kilometers) {
        if (!Double.isFinite(kilometers) || kilometers < 0) throw new IllegalArgumentException("Kilometers must be finite and non-negative");
        return kilometers / 1.609344;
    }
    public static void main(String[] args) {
        System.out.printf("%.3f km%n", milesToKilometers(10));
    }
}
